__global__ void initialize(float* x, float* y, float* z, int count) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < count) {
        x[i] = float(i % 7);
        y[i] = float(i % 11);
        z[i] = -1.0f;
    }
}

__global__ void stride_add(const float* x, const float* y, float* z,
                           int outputs, int stride) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < outputs) {
        int j = i * stride;
        z[j] = x[j] + y[j];
    }
}
```

